INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Ausbildender immer eine Einzelperson?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch ein Unternehmen sein"}, {"text": "Ja", "correct": false, "because": "Nicht nur Personen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich als Ausbildender?', 3, '[{"text": "Kompetenzen vermitteln", "correct": true, "because": "Wissen und Fähigkeiten"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben gehören zu einem Ausbildenden?', 5, '[{"text": "Wissensvermittlung", "correct": true, "because": "Kernaufgabe"}, {"text": "Betreuung", "correct": true, "because": "Unterstützt Lernende"}, {"text": "Marketing", "correct": false, "because": "Kein Ausbildungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Ausbildender muss qualifiziert sein. b) Er ist immer ein Arbeitgeber.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann auch extern sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich als Ausbildender?', 4, '[{"text": "Lernziele", "correct": false, "because": "Kern der Ausbildung"}, {"text": "Betreuung", "correct": false, "because": "Wichtig für Erfolg"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Ausbildender Schulungen plant?', 2, '[{"text": "Ja", "correct": true, "because": "Organisiert Lernprozesse"}, {"text": "Nein", "correct": false, "because": "Teil der Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Ausbildender in der Berufsausbildung?', 3, '[{"text": "Lehrer", "correct": true, "because": "Vermittelt Wissen"}, {"text": "Buchhalter", "correct": false, "because": "Andere Funktion"}, {"text": "Designer", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu den Pflichten eines Ausbildenden?', 5, '[{"text": "Ausbildungsplan erstellen", "correct": true, "because": "Strukturiert Lernprozess"}, {"text": "Auszubildende fördern", "correct": true, "because": "Unterstützt Entwicklung"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Ausbildungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Ausbildender ist für die Entwicklung verantwortlich. b) Er muss keine Qualifikation haben. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualifikation erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für einen Ausbildenden unwichtig?', 4, '[{"text": "Fachkompetenz", "correct": false, "because": "Grundlage"}, {"text": "Betreuung", "correct": false, "because": "Kernaufgabe"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Ausbildender pädagogische Fähigkeiten haben?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert Lernprozess"}, {"text": "Nein", "correct": false, "because": "Hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein guter Ausbildender?', 4, '[{"text": "Kompetente Auszubildende", "correct": true, "because": "Effektive Wissensvermittlung"}, {"text": "Motivation", "correct": true, "because": "Fördert Engagement"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Ausbildender nur Wissen vermittelt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Betreuung und Förderung"}, {"text": "Ja", "correct": false, "because": "Mehr als Wissen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich als Ausbildender?', 3, '[{"text": "Lernziele", "correct": true, "because": "Definiert Ausbildung"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Ausbildender plant die Ausbildung. b) Er ist nur für praktische Übungen zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Theorie wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlechter Ausbildender?', 5, '[{"text": "Mangelnde Kompetenz", "correct": true, "because": "Schwache Auszubildende"}, {"text": "Geringe Motivation", "correct": true, "because": "Frust bei Lernenden"}, {"text": "Schnelle Ausbildung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für einen Ausbildenden unwichtig?', 3, '[{"text": "Fachwissen", "correct": false, "because": "Grundlage"}, {"text": "Betreuung", "correct": false, "because": "Fördert Erfolg"}, {"text": "Bürodesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Ausbildender im Unternehmen angestellt sein?', 3, '[{"text": "Nein", "correct": true, "because": "Kann extern sein"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Ausbildender Feedback geben muss?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert Entwicklung"}, {"text": "Nein", "correct": false, "because": "Teil der Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Qualifikation wähle ich für einen Ausbildenden?', 4, '[{"text": "Fachliche Kompetenz", "correct": true, "because": "Wissen vermitteln"}, {"text": "Marketingfähigkeiten", "correct": false, "because": "Kein Bezug"}, {"text": "Designkenntnisse", "correct": false, "because": "Irrelevant"}]');
